fn car_x(t: i32, lane: i32, k: i32, w: i32) -> i32 {
    let spd: i32 = 2 + lane % 3;
    let pos: i32 = (t * spd + k * ((w + 100) / 2) + lane * 97) % (w + 100) - 50;
    if lane % 2 == 1 {
        w - 50 - pos
    } else {
        pos
    }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, w / 2 - 16);
        host::display::state_set(2, h - 48);
        host::display::state_set(3, 3);
        host::display::state_set(4, 0);
        host::display::state_set(5, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(6) == 0;
    host::display::state_set(6, down);
    let mut fx: i32 = host::display::state_get(1);
    let mut fy: i32 = host::display::state_get(2);
    if host::display::state_get(5) == 1 {
        host::display::clear(0x101010);
        host::display::draw_string(140, 180, "ROADKILL", 0xff4040, 4);
        host::display::draw_string(120, 250, "CROSSINGS", 0x808080, 2);
        host::display::draw_number(300, 244, host::display::state_get(4), 0xffffff, 3);
        host::display::draw_string(140, 320, "TAP TO HOP AGAIN", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        if tap {
            let dxp: i32 = host::display::pointer_x() - (fx + 16);
            let dyp: i32 = host::display::pointer_y() - (fy + 16);
            let mut ax: i32 = dxp;
            if ax < 0 { ax = -ax; }
            let mut ay: i32 = dyp;
            if ay < 0 { ay = -ay; }
            if ay >= ax {
                if dyp < 0 { fy = fy - 32; } else { fy = fy + 32; }
            } else {
                if dxp < 0 { fx = fx - 32; } else { fx = fx + 32; }
            }
            if fx < 0 { fx = 0; }
            if fx > w - 32 { fx = w - 32; }
            if fy > h - 48 { fy = h - 48; }
            if fy < 32 {
                host::display::state_set(4, host::display::state_get(4) + 1);
                fx = w / 2 - 16;
                fy = h - 48;
            }
        }
        let mut lane: i32 = 0;
        let mut hit: i32 = 0;
        while lane < 4 {
            let ly: i32 = 112 + lane * 72;
            let mut k: i32 = 0;
            while k < 2 {
                let cx: i32 = car_x(t, lane, k, w);
                if fx + 32 > cx && fx < cx + 56 && fy + 32 > ly + 10 && fy < ly + 38 {
                    hit = 1;
                }
                k = k + 1;
            }
            lane = lane + 1;
        }
        if hit == 1 {
            let lives: i32 = host::display::state_get(3) - 1;
            host::display::state_set(3, lives);
            if lives <= 0 { host::display::state_set(5, 1); }
            fx = w / 2 - 16;
            fy = h - 48;
        }
        host::display::state_set(1, fx);
        host::display::state_set(2, fy);
        host::display::clear(0x202028);
        host::display::fill_rect(0, 0, w, 64, 0x0a3818);
        host::display::fill_rect(0, h - 64, w, 64, 0x0a3818);
        let mut l2: i32 = 0;
        while l2 < 4 {
            let ly2: i32 = 112 + l2 * 72;
            let mut sx: i32 = 0;
            while sx < w {
                host::display::fill_rect(sx, ly2 + 46, 24, 4, 0x404048);
                sx = sx + 48;
            }
            let mut k2: i32 = 0;
            while k2 < 2 {
                let cx2: i32 = car_x(t, l2, k2, w);
                host::display::fill_rect(cx2, ly2 + 10, 56, 28, 0xff8822);
                host::display::fill_rect(cx2 + 8, ly2 + 14, 14, 8, 0x203040);
                k2 = k2 + 1;
            }
            l2 = l2 + 1;
        }
        host::display::fill_rect(fx + 2, fy + 2, 28, 28, 0x22cc44);
        host::display::fill_rect(fx + 6, fy + 6, 6, 6, 0xffffff);
        host::display::fill_rect(fx + 20, fy + 6, 6, 6, 0xffffff);
        host::display::draw_number(8, 6, host::display::state_get(4), 0xffffff, 2);
        let mut lf: i32 = 0;
        while lf < host::display::state_get(3) {
            host::display::fill_rect(w - 26 - lf * 18, 8, 12, 12, 0x22cc44);
            lf = lf + 1;
        }
    }
    host::display::present();
}
